function canBalance(s: string, locked: string): boolean {
  const n = s.length;
  const free: number[] = [];
  for (let i = 0; i < n; i++) if (locked[i] === "0") free.push(i);
  const chars = s.split("");
  for (let mask = 0; mask < 1 << free.length; mask++) {
    free.forEach((p, b) => { chars[p] = mask & (1 << b) ? "(" : ")"; });
    let bal = 0, ok = true;
    for (const c of chars) {
      bal += c === "(" ? 1 : -1;
      if (bal < 0) { ok = false; break; }
    }
    if (ok && bal === 0) return true;
  }
  return false;
}

