function canBalance(s: string, locked: string): boolean {
  const n = s.length;
  if (n % 2 === 1) return false;
  let bal = 0;
  for (let i = 0; i < n; i++) {
    bal += locked[i] === "0" || s[i] === "(" ? 1 : -1;
    if (bal < 0) return false;
  }
  bal = 0;
  for (let i = n - 1; i >= 0; i--) {
    bal += locked[i] === "0" || s[i] === ")" ? 1 : -1;
    if (bal < 0) return false;
  }
  return true;
}

